    function renderActivityLog() {
        const container = document.getElementById('activityLogContainer');
        container.innerHTML = '';

        if (!rawProductionData || rawProductionData.length === 0) {
            container.innerHTML = '<p class="text-xs text-center text-gray-400 italic">No recent activity</p>';
            return;
        }

        // Sort by timestamp descending
        const sorted = [...rawProductionData].sort((a,b) => new Date(b.timestamp) - new Date(a.timestamp));
        // Take top 10
        const recent = sorted.slice(0, 15);

        recent.forEach(item => {
            const date = new Date(item.timestamp);
            const timeStr = date.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
            const dateStr = date.toLocaleDateString([], {month: 'short', day: 'numeric'});

            const div = document.createElement('div');
            div.className = 'flex items-start gap-2 p-2 rounded hover:bg-gray-100 dark:hover:bg-slate-700/50 transition';

            // Icon based on type
            let iconClass;
            let actionText;
            let productInfo = `${item.product} - ${item.qty}`;

            if (item.type === 'Plan') {
                iconClass = 'fa-calendar-plus text-blue-500';
                actionText = 'Planned';
            } else if (item.type === 'Actual') {
                iconClass = 'fa-clipboard-check text-green-500';
                actionText = 'Input Actual';
            } else if (item.type === 'Edit') { // Assuming 'Edit' type for saved edits
                iconClass = 'fa-edit text-orange-500';
                actionText = 'Edited';
            } else {
                iconClass = 'fa-info-circle text-gray-500';
                actionText = 'Updated';
            }


            div.innerHTML = `
                <div class="mt-1"><i class="fas ${iconClass} text-xs"></i></div>
                <div class="flex-1 min-w-0">
                    <p class="text-xs font-bold text-gray-700 dark:text-gray-200 truncate">
                        ${item.user || 'Unknown'} <span class="font-normal text-gray-500">(${actionText})</span>
                    </p>
                    <p class="text-[10px] text-gray-500 truncate">${productInfo}</p>
                    <p class="text-[10px] text-gray-400 font-mono">${dateStr}, ${timeStr}</p>
