        // Update Plan
        if (planId && planId !== 'null') {
            updates.push({
                id: planId,
                type: 'Plan',
                qty: Number(newPlanQty),
                user: currentUser.username
            });
        }

        // Update Actual
        if (actualId && actualId !== 'null') {
             updates.push({
                id: actualId,
                type: 'Actual',
                qty: Number(newActualQty),
                batch: newBatch,
                user: currentUser.username
            });
