    if (offDays.some(d => d.date === newDate)) {
        alert('Date already marked as off day');
        return;
    }

    const newOffDay: OffDay = {
        id: Date.now().toString(),
        date: newDate,
        description: description || 'Scheduled Off',
        createdBy: user!.id
