import React, { useState, useMemo } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { CATEGORIES, PROCESSES } from '../../constants';
import type { ProductionEntry } from '../../types';
import { Trash2, Download, Calendar, List } from 'lucide-react';

export const ProductionLog: React.FC = () => {
  const { hasPermission, user } = useAuth();
  const [data, setData] = useState<ProductionEntry[]>(StorageService.getProductionData());

  // View Mode State
  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');

  // Filters
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [category, setCategory] = useState('All');
  const [processType, setProcessType] = useState('All');

  // Filter Data
  const filteredData = useMemo(() => {
    return data.filter(d => {
      const matchCat = category === 'All' || d.category === category;
      const matchProc = processType === 'All' || d.process === processType;
      const matchStart = !dateRange.start || d.date >= dateRange.start;
      const matchEnd = !dateRange.end || d.date <= dateRange.end;
      return matchCat && matchProc && matchStart && matchEnd;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [data, dateRange, category, processType]);

  // Aggregate Data for Monthly Summary
  const monthlyData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number, count: number }> = {};

    filteredData.forEach(d => {
        // Extract YYYY-MM
        const monthKey = d.date.substring(0, 7); 

        if (!groups[monthKey]) {
            groups[monthKey] = { plan: 0, actual: 0, count: 0 };
        }

        groups[monthKey].plan += d.planQuantity;
        groups[monthKey].actual += d.actualQuantity;
        groups[monthKey].count++;
    });

    return Object.entries(groups)
        .map(([month, stats]) => ({
            month,
            plan: stats.plan,
            actual: stats.actual,
            efficiency: stats.plan > 0 ? (stats.actual / stats.plan) * 100 : 0
        }))
        .sort((a, b) => b.month.localeCompare(a.month)); // Sort descending by month
  }, [filteredData]);

  const handleDelete = (id: string) => {
    if (!window.confirm("Are you sure you want to delete this entry?")) return;
    const newData = data.filter(d => d.id !== id);
    StorageService.saveProductionData(newData);
    setData(newData);
    StorageService.addLog({
      userId: user!.id,
      userName: user!.name,
      action: 'DELETE_ENTRY',
      details: `Deleted production entry ID ${id}`
    });
  };

  const calculateEfficiency = (actual: number, plan: number) => {
    if (plan === 0) return 0;
    return ((actual / plan) * 100).toFixed(1);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';

    if (viewMode === 'daily') {
        headers = ["Date", "Category", "Process", "Product", "Plan", "Actual", "Efficiency %", "Batch No", "Manpower"];
        rows = filteredData.map(d => [
            d.date, 
            d.category, 
            d.process, 
            `"${d.productName}"`, // Quote strings to prevent comma issues
            d.planQuantity, 
            d.actualQuantity, 
            calculateEfficiency(d.actualQuantity, d.planQuantity), 
            d.batchNo || '', 
            d.manpower || ''
        ]);
        filename = `production_log_daily_${new Date().toISOString().split('T')[0]}.csv`;
    } else {
        headers = ["Month", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = monthlyData.map(m => [
            m.month,
            m.plan,
            m.actual,
            m.efficiency.toFixed(2)
        ]);
        filename = `production_summary_monthly_${new Date().toISOString().split('T')[0]}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," 
      + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Production Reports</h2>

        <div className="flex items-center bg-white dark:bg-slate-800 rounded-lg p-1 border border-gray-200 dark:border-slate-700 shadow-sm">
            <button 
                onClick={() => setViewMode('daily')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition ${
                    viewMode === 'daily' 
                    ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300' 
                    : 'text-gray-500 hover:text-gray-700 dark:text-gray-400'
                }`}
            >
                <List className="w-4 h-4" /> Daily Log
            </button>
            <button 
                onClick={() => setViewMode('monthly')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition ${
                    viewMode === 'monthly' 
                    ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300' 
                    : 'text-gray-500 hover:text-gray-700 dark:text-gray-400'
                }`}
            >
                <Calendar className="w-4 h-4" /> Monthly Summary
            </button>
        </div>

        <button 
            onClick={downloadCSV}
            className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-bold hover:bg-emerald-700 transition shadow-lg shadow-emerald-500/20"
        >
            <Download className="w-4 h-4" /> Export Excel
        </button>
      </div>

      {/* Filters */}
      <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 grid grid-cols-1 md:grid-cols-4 gap-4 animate-in fade-in slide-in-from-bottom-4">
        <div>
           <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block uppercase font-bold">Start Date</label>
           <input type="date" className="w-full text-sm border dark:border-slate-600 bg-transparent dark:text-white p-2 rounded focus:ring-2 focus:ring-indigo-500" onChange={e => setDateRange(prev => ({...prev, start: e.target.value}))} />
        </div>
        <div>
           <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block uppercase font-bold">End Date</label>
           <input type="date" className="w-full text-sm border dark:border-slate-600 bg-transparent dark:text-white p-2 rounded focus:ring-2 focus:ring-indigo-500" onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))} />
        </div>
        <div>
           <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block uppercase font-bold">Category</label>
           <select className="w-full text-sm border dark:border-slate-600 bg-transparent dark:text-white p-2 rounded focus:ring-2 focus:ring-indigo-500" onChange={e => setCategory(e.target.value)}>
              <option value="All">All Categories</option>
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
           </select>
        </div>
        <div>
           <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block uppercase font-bold">Process</label>
           <select className="w-full text-sm border dark:border-slate-600 bg-transparent dark:text-white p-2 rounded focus:ring-2 focus:ring-indigo-500" onChange={e => setProcessType(e.target.value)}>
              <option value="All">All Processes</option>
              {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
           </select>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-50 dark:bg-slate-700 text-gray-700 dark:text-slate-200 font-semibold border-b border-gray-200 dark:border-slate-600">
              {viewMode === 'daily' ? (
                  <tr>
                    <th className="px-6 py-4">Date</th>
                    <th className="px-6 py-4">Product</th>
                    <th className="px-6 py-4">Category / Process</th>
                    <th className="px-6 py-4 text-right">Plan</th>
                    <th className="px-6 py-4 text-right">Actual</th>
                    <th className="px-6 py-4 text-right">Eff. %</th>
                    <th className="px-6 py-4">Batch No</th>
                    {hasPermission(['admin', 'manager']) && <th className="px-6 py-4 text-center">Actions</th>}
                  </tr>
              ) : (
                  <tr>
                    <th className="px-6 py-4">Month</th>
                    <th className="px-6 py-4 text-right">Total Plan</th>
                    <th className="px-6 py-4 text-right">Total Actual</th>
                    <th className="px-6 py-4 text-right">Overall Efficiency</th>
                    <th className="px-6 py-4">Performance Status</th>
                  </tr>
              )}
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
              {/* DAILY VIEW */}
              {viewMode === 'daily' && (
                  filteredData.length === 0 ? (
                    <tr><td colSpan={8} className="text-center py-12 text-gray-400">No records found matching filters</td></tr>
                  ) : filteredData.map(entry => {
                    const eff = Number(calculateEfficiency(entry.actualQuantity, entry.planQuantity));
                    return (
                      <tr key={entry.id} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition">
                        <td className="px-6 py-3 whitespace-nowrap text-gray-600 dark:text-gray-300 font-mono text-xs">{entry.date}</td>
                        <td className="px-6 py-3 font-medium text-gray-800 dark:text-white">{entry.productName}</td>
                        <td className="px-6 py-3">
                            <div className="text-xs">
                                <span className="font-semibold text-slate-700 dark:text-slate-200">{entry.category}</span>
                                <span className="text-gray-300 dark:text-slate-500 mx-2">|</span>
                                <span className="text-slate-500 dark:text-slate-400">{entry.process}</span>
                            </div>
                        </td>
                        <td className="px-6 py-3 text-right font-mono text-blue-600 dark:text-blue-400">{entry.planQuantity}</td>
