                        <td className="px-6 py-3 text-right">
                            <span className={`px-2 py-0.5 rounded text-xs font-bold ${
                                eff >= 100 ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' :
