      if (!processMap.has(d.process)) {
        processMap.set(d.process, { process: d.process, Plan: 0, Actual: 0 });
      }
      const p = processMap.get(d.process)!;
      p.Plan += d.planQuantity;
      p.Actual += d.actualQuantity;

      // Monthly Aggregation
      const monthKey = d.date.substring(0, 7); // YYYY-MM
      if (!monthlyGroups[monthKey]) {
          monthlyGroups[monthKey] = { plan: 0, actual: 0 };
      }
      monthlyGroups[monthKey].plan += d.planQuantity;
      monthlyGroups[monthKey].actual += d.actualQuantity;
    });

    const monthlyStats = Object.entries(monthlyGroups)
        .map(([month, s]) => ({
            month,
            plan: s.plan,
            actual: s.actual,
            efficiency: s.plan > 0 ? (s.actual / s.plan) * 100 : 0
        }))
        .sort((a, b) => b.month.localeCompare(a.month));

    return {
      filteredData: relevant.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()),
      stats: { totalPlan, totalActual },
      chartData: Array.from(processMap.values()),
      monthlyData: monthlyStats
    };
  }, [productionData, category]);

  // Group data by Date for the Daily View Table
  const dailyGroups = useMemo(() => {
    if (viewMode === 'monthly') return [];

    const groups: Record<string, { date: string; entries: ProductionEntry[]; offDay?: string }> = {};

    // Group Production Entries
    filteredData.forEach(d => {
        if (!groups[d.date]) groups[d.date] = { date: d.date, entries: [] };
        groups[d.date].entries.push(d);
    });

    // Group OffDays
    offDays.forEach(od => {
        if (!groups[od.date]) groups[od.date] = { date: od.date, entries: [] };
        groups[od.date].offDay = od.description;
    });

    return Object.values(groups).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [filteredData, offDays, viewMode]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Delete this record?")) return;
      const newData = productionData.filter(p => p.id !== id);
      StorageService.saveProductionData(newData);
      triggerRefresh();
  };

  const calculateEfficiency = (actual: number, plan: number) => {
    if (plan === 0) return 0;
    return ((actual / plan) * 100).toFixed(0);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';

    if (viewMode === 'daily') {
        headers = ["Date", "Category", "Process", "Product", "Plan", "Actual", "Efficiency %", "Batch No", "Manpower"];
        rows = filteredData.map(d => [
            d.date, 
            d.category, 
            d.process, 
            `"${d.productName}"`, 
            d.planQuantity, 
            d.actualQuantity, 
            calculateEfficiency(d.actualQuantity, d.planQuantity), 
            d.batchNo || '', 
            d.manpower || ''
        ]);
        filename = `${category}_daily_log_${new Date().toISOString().split('T')[0]}.csv`;
    } else {
        headers = ["Month", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = monthlyData.map(m => [
            m.month,
            m.plan,
            m.actual,
            m.efficiency.toFixed(2)
        ]);
        filename = `${category}_monthly_summary_${new Date().toISOString().split('T')[0]}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," 
      + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
