                                        </span>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
      </div>

      {editingEntry && (
        <EditEntryModal 
            entry={editingEntry} 
            onClose={() => setEditingEntry(null)} 
        />
      )}
    </div>
  );
