import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import type { ProductionEntry } from '../../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer 
} from 'recharts';
import { ClipboardList, CheckCircle, RefreshCw, Download, List, Calendar, Trash2, Edit2 } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { EditEntryModal } from '../modals/EditEntryModal';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { hasPermission } = useAuth();

  // View Mode State
  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');
  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);

  // Fetch data
  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays()
    };
  }, [refreshKey]);

  // Consolidate data for table and charts
  const { filteredData, stats, chartData, monthlyData } = useMemo(() => {
    const relevant = productionData.filter(d => d.category === category);

    // Stats
    let totalPlan = 0;
    let totalActual = 0;

    // Chart data aggregation by Process
    const processMap = new Map<string, {process: string, Plan: number, Actual: number}>();

    // Monthly aggregation
    const monthlyGroups: Record<string, { plan: number, actual: number }> = {};

    relevant.forEach(d => {
      totalPlan += d.planQuantity;
      totalActual += d.actualQuantity;

      // Chart Aggregation
      if (!processMap.has(d.process)) {
        processMap.set(d.process, { process: d.process, Plan: 0, Actual: 0 });
      }
      const p = processMap.get(d.process)!;
      p.Plan += d.planQuantity;
      p.Actual += d.actualQuantity;

      // Monthly Aggregation
      const monthKey = d.date.substring(0, 7); // YYYY-MM
      if (!monthlyGroups[monthKey]) {
          monthlyGroups[monthKey] = { plan: 0, actual: 0 };
      }
      monthlyGroups[monthKey].plan += d.planQuantity;
      monthlyGroups[monthKey].actual += d.actualQuantity;
    });

    const monthlyStats = Object.entries(monthlyGroups)
        .map(([month, s]) => ({
            month,
            plan: s.plan,
            actual: s.actual,
            efficiency: s.plan > 0 ? (s.actual / s.plan) * 100 : 0
        }))
        .sort((a, b) => b.month.localeCompare(a.month));

    return {
      filteredData: relevant.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()),
      stats: { totalPlan, totalActual },
      chartData: Array.from(processMap.values()),
      monthlyData: monthlyStats
    };
  }, [productionData, category]);

  // Group data by Date for the Daily View Table
  const dailyGroups = useMemo(() => {
    if (viewMode === 'monthly') return [];

    const groups: Record<string, { date: string; entries: ProductionEntry[]; offDay?: string }> = {};

    // Group Production Entries
    filteredData.forEach(d => {
        if (!groups[d.date]) groups[d.date] = { date: d.date, entries: [] };
        groups[d.date].entries.push(d);
    });

    // Group OffDays
    offDays.forEach(od => {
        if (!groups[od.date]) groups[od.date] = { date: od.date, entries: [] };
        groups[od.date].offDay = od.description;
    });

    return Object.values(groups).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [filteredData, offDays, viewMode]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Delete this record?")) return;
      const newData = productionData.filter(p => p.id !== id);
      StorageService.saveProductionData(newData);
      triggerRefresh();
  };

  const calculateEfficiency = (actual: number, plan: number) => {
    if (plan === 0) return 0;
    return ((actual / plan) * 100).toFixed(0);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';

    if (viewMode === 'daily') {
        headers = ["Date", "Category", "Process", "Product", "Plan", "Actual", "Efficiency %", "Batch No", "Manpower"];
        rows = filteredData.map(d => [
            d.date, 
            d.category, 
            d.process, 
            `"${d.productName}"`, 
            d.planQuantity, 
            d.actualQuantity, 
            calculateEfficiency(d.actualQuantity, d.planQuantity), 
            d.batchNo || '', 
            d.manpower || ''
        ]);
        filename = `${category}_daily_log_${new Date().toISOString().split('T')[0]}.csv`;
    } else {
        headers = ["Month", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = monthlyData.map(m => [
            m.month,
            m.plan,
            m.actual,
            m.efficiency.toFixed(2)
        ]);
        filename = `${category}_monthly_summary_${new Date().toISOString().split('T')[0]}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," 
      + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-blue-500 flex justify-between items-center transform transition hover:scale-[1.01]">
            <div>
                <p className="text-sm font-medium text-slate-500 dark:text-slate-400">Total Plan Quantity</p>
                <h3 className="text-3xl font-extrabold mt-1 text-blue-600 dark:text-blue-400">{stats.totalPlan.toLocaleString()}</h3>
            </div>
            <div className="w-12 h-12 bg-blue-100 dark:bg-blue-900/50 rounded-full flex items-center justify-center text-blue-600 dark:text-blue-400">
                <ClipboardList className="w-6 h-6" />
            </div>
        </div>
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-emerald-500 flex justify-between items-center transform transition hover:scale-[1.01]">
            <div>
                <p className="text-sm font-medium text-slate-500 dark:text-slate-400">Total Actual Quantity</p>
                <h3 className="text-3xl font-extrabold mt-1 text-emerald-600 dark:text-emerald-400">{stats.totalActual.toLocaleString()}</h3>
            </div>
            <div className="w-12 h-12 bg-emerald-100 dark:bg-emerald-900/50 rounded-full flex items-center justify-center text-emerald-600 dark:text-emerald-400">
                <CheckCircle className="w-6 h-6" />
            </div>
        </div>
      </div>

      {/* Chart */}
      <div className="glass-panel rounded-2xl p-6">
          <h3 className="font-bold text-lg mb-4 text-slate-700 dark:text-slate-200">Production by Process</h3>
          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="process" tick={{fontSize: 12, fill: '#64748b'}} axisLine={false} tickLine={false} />
                <YAxis tick={{fontSize: 12, fill: '#64748b'}} axisLine={false} tickLine={false} />
                <Tooltip 
                    contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1)' }}
                    cursor={{fill: 'transparent'}}
                />
                <Legend />
                <Bar dataKey="Plan" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40} />
                <Bar dataKey="Actual" fill="#10b981" radius={[4, 4, 0, 0]} barSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
      </div>

      {/* Production Log */}
      <div className="glass-panel rounded-2xl overflow-hidden min-h-[400px] flex flex-col">
        <div className="p-5 border-b border-gray-100 dark:border-slate-700/50 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white/50 dark:bg-slate-800/50">
            <h3 className="font-bold text-lg flex items-center gap-2 text-slate-700 dark:text-slate-200">
                <i className="fas fa-table text-indigo-500"></i> Production Log
            </h3>

            <div className="flex flex-wrap items-center gap-3">
                <div className="flex items-center bg-gray-100 dark:bg-slate-900 rounded-lg p-1">
                    <button 
                        onClick={() => setViewMode('daily')}
                        className={`flex items-center gap-1 px-3 py-1.5 rounded-md text-xs font-bold transition ${
                            viewMode === 'daily' 
                            ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-sm' 
                            : 'text-gray-500 dark:text-gray-400 hover:text-gray-700'
                        }`}
                    >
                        <List className="w-3 h-3" /> Daily
                    </button>
                    <button 
                        onClick={() => setViewMode('monthly')}
                        className={`flex items-center gap-1 px-3 py-1.5 rounded-md text-xs font-bold transition ${
                            viewMode === 'monthly' 
                            ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-sm' 
                            : 'text-gray-500 dark:text-gray-400 hover:text-gray-700'
                        }`}
                    >
                        <Calendar className="w-3 h-3" /> Monthly
                    </button>
                </div>

                <button onClick={downloadCSV} className="flex items-center gap-1 px-3 py-1.5 bg-emerald-600 text-white text-xs font-bold rounded-lg hover:bg-emerald-700 transition">
                    <Download className="w-3 h-3" /> Export
                </button>

                <button onClick={triggerRefresh} className="text-sm text-indigo-600 dark:text-indigo-400 font-semibold hover:underline flex items-center gap-1">
                    <RefreshCw className="w-3 h-3" />
                </button>
            </div>
        </div>

        <div className="p-4 space-y-6 flex-1 bg-gray-50/50 dark:bg-slate-900/20">
            {/* DAILY VIEW - GROUPED BY DATE */}
            {viewMode === 'daily' && (
                <>
                    {dailyGroups.length === 0 && (
                        <div className="flex flex-col items-center justify-center h-48 text-slate-400">
                            <p>No data found.</p>
                        </div>
                    )}

                    {dailyGroups.map((group, idx) => {
                        const dateObj = new Date(group.date);
                        const monthStr = dateObj.toLocaleString('default', { month: 'short', year: 'numeric' }).toUpperCase();
                        const dayName = dateObj.toLocaleDateString('default', { weekday: 'long' }).toUpperCase();
                        const showMonthHeader = idx === 0 || 
                            new Date(dailyGroups[idx - 1].date).getMonth() !== dateObj.getMonth();

                        const totalDailyActual = group.entries.reduce((sum, e) => sum + e.actualQuantity, 0);

                        return (
                            <React.Fragment key={group.date}>
                                {showMonthHeader && (
                                    <div className="relative text-center my-8">
                                        <span className="bg-gray-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 px-4 py-1 rounded-full text-xs font-bold uppercase tracking-wider relative z-10">
                                            {monthStr}
                                        </span>
                                        <div className="absolute top-1/2 left-0 w-full h-px bg-gray-300 dark:bg-slate-700 -z-0"></div>
                                    </div>
                                )}

                                <div className={`rounded-xl overflow-hidden shadow-sm border border-gray-200 dark:border-slate-700 ${group.offDay ? 'bg-red-50 dark:bg-red-900/10' : 'bg-white dark:bg-slate-800'}`}>
                                    {/* Date Header */}
                                    <div className={`p-4 flex flex-wrap justify-between items-center ${group.offDay ? 'bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-200' : 'bg-slate-800 text-white'}`}>
                                        <div className="flex items-center gap-3">
                                            <span className="text-lg font-bold"><i className="fas fa-calendar-day mr-2 opacity-70"></i>{group.date}</span>
                                            <span className="text-xs font-medium opacity-70 uppercase tracking-wide bg-black/20 px-2 py-0.5 rounded">{dayName}</span>
                                            {group.offDay && <span className="bg-red-600 text-white px-3 py-0.5 rounded text-xs font-bold uppercase tracking-wider">OFF DAY: {group.offDay}</span>}
                                        </div>
                                        {!group.offDay && group.entries.length > 0 && (
                                            <div className="bg-slate-700 dark:bg-slate-900 px-3 py-1 rounded-lg text-xs font-bold text-white border border-slate-600">
                                                Total Actual: {totalDailyActual}
                                            </div>
                                        )}
                                    </div>

                                    {/* Production Table or Off Day Message */}
                                    {group.entries.length > 0 ? (
                                        <div className="overflow-x-auto">
                                            <table className="w-full text-sm text-left">
                                                <thead className="bg-gray-50 dark:bg-slate-900/50 text-gray-500 dark:text-gray-400 font-bold text-[10px] uppercase border-b border-gray-100 dark:border-slate-700">
                                                    <tr>
                                                        <th className="px-4 py-3">Process</th>
                                                        <th className="px-4 py-3">Product</th>
                                                        <th className="px-4 py-3 text-right text-blue-600 dark:text-blue-400">Plan Qty</th>
                                                        <th className="px-4 py-3 text-right text-emerald-600 dark:text-emerald-400">Actual Qty</th>
                                                        <th className="px-4 py-3 text-center">Efficiency</th>
                                                        <th className="px-4 py-3 text-center">Batch No</th>
                                                        <th className="px-4 py-3 text-center">Manpower</th>
                                                        {hasPermission(['manager', 'admin']) && <th className="px-4 py-3 text-center">Action</th>}
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                                                    {group.entries.map(entry => {
                                                        const eff = Number(calculateEfficiency(entry.actualQuantity, entry.planQuantity));
                                                        let effColor = 'text-red-500 font-bold';
                                                        if(eff >= 80) effColor = 'text-emerald-500 font-bold';
                                                        else if(eff >= 50) effColor = 'text-yellow-500 font-bold';

                                                        return (
                                                            <tr key={entry.id} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition">
                                                                <td className="px-4 py-3">
                                                                    <span className="bg-indigo-50 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-300 px-2 py-1 rounded text-xs font-bold border border-indigo-100 dark:border-indigo-800">
                                                                        {entry.process}
                                                                    </span>
                                                                </td>
                                                                <td className="px-4 py-3 font-bold text-slate-700 dark:text-slate-200">{entry.productName}</td>
                                                                <td className="px-4 py-3 text-right font-mono text-blue-600 dark:text-blue-400 font-bold">{entry.planQuantity}</td>
                                                                <td className="px-4 py-3 text-right font-mono text-emerald-600 dark:text-emerald-400 font-bold">{entry.actualQuantity}</td>
                                                                <td className={`px-4 py-3 text-center ${effColor}`}>
                                                                    {eff}%
                                                                </td>
                                                                <td className="px-4 py-3 text-center font-mono text-xs text-slate-500 dark:text-gray-400">{entry.batchNo || '-'}</td>
                                                                <td className="px-4 py-3 text-center font-bold dark:text-gray-300">{entry.manpower || 0}</td>
                                                                {hasPermission(['manager', 'admin']) && (
                                                                    <td className="px-4 py-3 text-center flex justify-center gap-2">
                                                                        <button 
                                                                            onClick={() => setEditingEntry(entry)}
                                                                            className="text-indigo-400 hover:text-indigo-600 transition-colors p-1.5 rounded-full hover:bg-indigo-50 dark:hover:bg-indigo-900/20"
                                                                            title="Edit Entry"
                                                                        >
                                                                            <Edit2 className="w-4 h-4" />
                                                                        </button>
                                                                        <button 
                                                                            onClick={() => handleDelete(entry.id)}
                                                                            className="text-gray-400 hover:text-red-500 transition-colors p-1.5 rounded-full hover:bg-red-50 dark:hover:bg-red-900/20"
                                                                            title="Delete Entry"
                                                                        >
                                                                            <Trash2 className="w-4 h-4" />
                                                                        </button>
                                                                    </td>
                                                                )}
                                                            </tr>
                                                        );
                                                    })}
                                                </tbody>
                                            </table>
                                        </div>
                                    ) : (
                                        <div className={`p-8 text-center flex flex-col items-center justify-center ${group.offDay ? 'text-red-500' : 'text-gray-400'}`}>
                                            {group.offDay ? (
                                                <>
                                                    <span className="font-bold text-lg uppercase tracking-widest">{group.offDay}</span>
                                                    <span className="text-xs opacity-70 mt-1">Production Halted</span>
                                                </>
                                            ) : (
                                                <span className="italic">No production data recorded for this day.</span>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </React.Fragment>
                        );
                    })}
                </>
            )}

            {/* MONTHLY SUMMARY VIEW */}
            {viewMode === 'monthly' && (
                <div className="overflow-x-auto bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-200 dark:border-slate-700">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-gray-100 dark:bg-slate-700 text-gray-700 dark:text-slate-200">
                            <tr>
                                <th className="px-6 py-4 rounded-l-lg">Month</th>
                                <th className="px-6 py-4 text-right">Total Plan</th>
                                <th className="px-6 py-4 text-right">Total Actual</th>
                                <th className="px-6 py-4 text-right">Overall Eff.</th>
                                <th className="px-6 py-4 rounded-r-lg text-center">Status</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                            {monthlyData.length === 0 ? (
                                <tr><td colSpan={5} className="text-center py-8 text-gray-400">No data available</td></tr>
                            ) : monthlyData.map(m => (
                                <tr key={m.month} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition">
                                    <td className="px-6 py-4 font-bold text-gray-800 dark:text-white">
                                        {new Date(m.month + '-01').toLocaleDateString('default', { month: 'long', year: 'numeric' })}
                                    </td>
                                    <td className="px-6 py-4 text-right font-mono text-blue-600 dark:text-blue-400 font-bold">{m.plan.toLocaleString()}</td>
                                    <td className="px-6 py-4 text-right font-mono text-emerald-600 dark:text-emerald-400 font-bold">{m.actual.toLocaleString()}</td>
                                    <td className="px-6 py-4 text-right">
                                        <span className={`font-bold ${m.efficiency >= 80 ? 'text-emerald-600' : 'text-red-500'}`}>{m.efficiency.toFixed(1)}%</span>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wide ${
                                            m.efficiency >= 90 ? 'bg-emerald-100 text-emerald-700' : 
                                            m.efficiency >= 80 ? 'bg-blue-100 text-blue-700' : 'bg-red-100 text-red-700'
                                        }`}>
                                            {m.efficiency >= 90 ? 'Excellent' : m.efficiency >= 80 ? 'Good' : 'Review'}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
      </div>

      {editingEntry && (
        <EditEntryModal 
            entry={editingEntry} 
            onClose={() => setEditingEntry(null)} 
        />
      )}
    </div>
  );
};

