import React, { createContext, useContext, useState, ReactNode, useCallback } from 'react';
import { X, CheckCircle, AlertCircle, Info } from 'lucide-react';

export type NotificationType = 'success' | 'error' | 'info';

interface Notification {
  id: string;
  type: NotificationType;
  message: string;
}

interface NotificationContextType {
  notify: (type: NotificationType, message: string) => void;
}

const NotificationContext = createContext<NotificationContextType | undefined>(undefined);

export const NotificationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const notify = useCallback((type: NotificationType, message: string) => {
    const id = Date.now().toString();
    setNotifications((prev) => [...prev, { id, type, message }]);

    // Auto dismiss after 4 seconds
    setTimeout(() => {
      setNotifications((prev) => prev.filter((n) => n.id !== id));
    }, 4000);
  }, []);

  const dismiss = (id: string) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));
  };

  return (
    <NotificationContext.Provider value={{ notify }}>
      {children}

      {/* Toast Container */}
      <div className="fixed top-20 right-4 z-50 flex flex-col gap-2 pointer-events-none">
        {notifications.map((n) => (
          <div 
            key={n.id}
            className={`
              pointer-events-auto flex items-center gap-3 px-4 py-3 rounded-xl shadow-lg border animate-in slide-in-from-right-full duration-300 w-80 bg-white dark:bg-slate-800
              ${n.type === 'success' ? 'border-l-4 border-l-emerald-500 border-gray-100 dark:border-slate-700' : ''}
              ${n.type === 'error' ? 'border-l-4 border-l-red-500 border-gray-100 dark:border-slate-700' : ''}
              ${n.type === 'info' ? 'border-l-4 border-l-blue-500 border-gray-100 dark:border-slate-700' : ''}
            `}
          >
            <div className={`
              p-1 rounded-full 
              ${n.type === 'success' ? 'text-emerald-500 bg-emerald-50 dark:bg-emerald-900/20' : ''}
              ${n.type === 'error' ? 'text-red-500 bg-red-50 dark:bg-red-900/20' : ''}
              ${n.type === 'info' ? 'text-blue-500 bg-blue-50 dark:bg-blue-900/20' : ''}
            `}>
              {n.type === 'success' && <CheckCircle className="w-5 h-5" />}
              {n.type === 'error' && <AlertCircle className="w-5 h-5" />}
              {n.type === 'info' && <Info className="w-5 h-5" />}
            </div>
            <p className="flex-1 text-sm font-medium text-slate-700 dark:text-slate-200">{n.message}</p>
            <button onClick={() => dismiss(n.id)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
              <X className="w-4 h-4" />
            </button>
          </div>
        ))}
      </div>
    </NotificationContext.Provider>
  );
};

export const useNotification = () => {
  const context = useContext(NotificationContext);
  if (!context) throw new Error('useNotification must be used within NotificationProvider');
  return context;
};
