import React, { createContext, useContext, useState, useEffect } from 'react';
import type { ReactNode } from 'react';
import type { User, Role } from '../types';
import { StorageService } from '../services/storageService';
import { INITIAL_USERS } from '../constants';
import { useNotification } from './NotificationContext';

interface AuthContextType {
  user: User | null;
  login: (username: string, pass: string) => boolean;
  logout: () => void;
  hasPermission: (roles: Role[]) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const { notify } = useNotification();

  useEffect(() => {
    const session = StorageService.getSession();
    if (session) {
      setUser(session);
    }
  }, []);

  const login = (username: string, pass: string) => {
    const storedUsers = StorageService.getUsers();
    // Combine initial users and stored users for authentication check
    // We check against 'name' or 'email' to support both legacy email logins and new username logins
    const allUsers = [...INITIAL_USERS, ...storedUsers];

    const targetUser = allUsers.find(u => 
        u.name.toLowerCase() === username.toLowerCase() || 
        u.email.toLowerCase() === username.toLowerCase()
    );

    if (targetUser && targetUser.password === pass) {
      setUser(targetUser);
      StorageService.setSession(targetUser);
      return true;
    }
    return false;
  };

  const logout = () => {
    setUser(null);
    StorageService.setSession(null);
    notify('info', 'You have logged out.');
  };

  const hasPermission = (allowedRoles: Role[]) => {
    if (!user) return false;
    return allowedRoles.includes(user.role);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, hasPermission }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    // This might happen if used outside provider, but since notification provider is outside auth,
    // we can't easily use 'useNotification' inside AuthProvider unless we re-structure.
    // However, for this specific request, I moved 'useNotification' inside AuthProvider component above.
    // If that causes a circular dependency or context order issue in App.tsx, we need to be careful.
    // In App.tsx: NotificationProvider wraps AuthProvider, so 'useNotification' IS available inside AuthProvider.
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
