  if (!GOOGLE_SHEET_API_URL || GOOGLE_SHEET_API_URL.includes("YOUR_GOOGLE")) return null;
  try {
    const res = await fetch(`${GOOGLE_SHEET_API_URL}?action=read&sheet=${sheetName}`);
    const data = await res.json();
    return Array.isArray(data) ? data : null;
  } catch (error) {
    console.error(`Failed to fetch ${sheetName}`, error);
    return null;
  }
};

// Initialize & Sync Down
const init = async () => {
  // 1. Setup Local defaults if empty
  if (!localStorage.getItem(KEYS.USERS)) localStorage.setItem(KEYS.USERS, JSON.stringify(INITIAL_USERS));
  if (!localStorage.getItem(KEYS.OFF_DAYS)) localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(INITIAL_OFF_DAYS));
  if (!localStorage.getItem(KEYS.PRODUCTION)) localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(generateSeedProductionData()));
  if (!localStorage.getItem(KEYS.LOGS)) localStorage.setItem(KEYS.LOGS, JSON.stringify([]));

  // 2. Try to fetch fresh data from Google Sheet (Async)
  const users = await fetchFromSheet('Users');
  if (users) localStorage.setItem(KEYS.USERS, JSON.stringify(users));

  const production = await fetchFromSheet('Production');
  if (production) localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(production));

  const offDays = await fetchFromSheet('OffDays');
  if (offDays) localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(offDays));

  const logs = await fetchFromSheet('Logs');
  if (logs) localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));
};

// Start sync on load
init();

export const StorageService = {
  // Users
  getUsers: (): User[] => JSON.parse(localStorage.getItem(KEYS.USERS) || '[]'),
  saveUsers: (users: User[]) => {
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
    syncToSheet('Users', users);
  },

  // Production
  getProductionData: (): ProductionEntry[] => JSON.parse(localStorage.getItem(KEYS.PRODUCTION) || '[]'),
  saveProductionData: (data: ProductionEntry[]) => {
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(data));
    syncToSheet('Production', data);
  },

  // Off Days
  getOffDays: (): OffDay[] => JSON.parse(localStorage.getItem(KEYS.OFF_DAYS) || '[]'),
  saveOffDays: (days: OffDay[]) => {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(days));
    syncToSheet('OffDays', days);
  },

  // Logs
  getLogs: (): ActivityLog[] => JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]'),
  addLog: (log: Omit<ActivityLog, 'id' | 'timestamp'>) => {
    const logs = StorageService.getLogs();
    const newLog: ActivityLog = {
      ...log,
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
    };
    logs.unshift(newLog); 
    if (logs.length > 1000) logs.pop();

    localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));
    syncToSheet('Logs', logs);
  },

  // Session (No sync needed for session)
  getSession: (): User | null => {
    const session = localStorage.getItem(KEYS.CURRENT_USER);
    return session ? JSON.parse(session) : null;
  },
  setSession: (user: User | null) => {
    if (user) localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
    else localStorage.removeItem(KEYS.CURRENT_USER);
  }
};
