                    Input Actual
                </button>
            )}
        </div>

        <div className="p-6 relative">
            <button onClick={onClose} className="absolute top-2 right-4 text-gray-400 hover:text-red-500"><X /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} 
                        className="w-full p-2.5 rounded-lg border dark:bg-slate-900 dark:border-slate-700" />
                </div>

                {tab === 'Plan' ? (
