                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className="w-full p-2.5 rounded-lg border dark:bg-slate-900 dark:border-slate-700">
