## src/services/storageService.ts

I have added a `subscribe` system here. When data arrives from Google Sheets, it triggers `notifyChange()`, which tells the app to update. I also removed the `generateSeedProductionData()` call so you don't see fake data on new devices.

```typescript
import type { User, ProductionEntry, OffDay, ActivityLog } from '../types';
import { INITIAL_USERS, INITIAL_OFF_DAYS, GOOGLE_SHEET_API_URL } from '../constants';

const KEYS = {
  USERS: 'nexus_users',
  PRODUCTION: 'nexus_production',
  OFF_DAYS: 'nexus_off_days',
  LOGS: 'nexus_activity_logs',
  CURRENT_USER: 'nexus_current_user_session',
};

// Simple Event System to notify React components when data changes/loads
const listeners: (() => void)[] = [];

const notifyChange = () => {
  listeners.forEach(l => l());
};

// API Helper
const syncToSheet = async (sheetName: string, data: any[]) => {
  if (!GOOGLE_SHEET_API_URL || GOOGLE_SHEET_API_URL.includes("YOUR_GOOGLE")) return;
  try {
    await fetch(GOOGLE_SHEET_API_URL, {
      method: 'POST',
      mode: 'no-cors',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'save', sheet: sheetName, data })
    });
    // console.log(`Synced ${sheetName}`); 
  } catch (error) {
    console.error(`Failed to sync ${sheetName}`, error);
  }
};

const fetchFromSheet = async (sheetName: string) => {
  if (!GOOGLE_SHEET_API_URL || GOOGLE_SHEET_API_URL.includes("YOUR_GOOGLE")) return null;
  try {
    const res = await fetch(`${GOOGLE_SHEET_API_URL}?action=read&sheet=${sheetName}`);
    const data = await res.json();
    return Array.isArray(data) ? data : null;
  } catch (error) {
    console.error(`Failed to fetch ${sheetName}`, error);
    return null;
  }
};

// Initialize & Sync Down
const init = async () => {
  // 1. Setup Local defaults if empty
  // Users: Keep default admin so you can login on fresh device
  if (!localStorage.getItem(KEYS.USERS)) localStorage.setItem(KEYS.USERS, JSON.stringify(INITIAL_USERS));

  // OffDays: Keep defaults or empty
  if (!localStorage.getItem(KEYS.OFF_DAYS)) localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(INITIAL_OFF_DAYS));

  // Production: START EMPTY (No Demo Data)
  if (!localStorage.getItem(KEYS.PRODUCTION)) localStorage.setItem(KEYS.PRODUCTION, JSON.stringify([]));

  // Logs: Empty
  if (!localStorage.getItem(KEYS.LOGS)) localStorage.setItem(KEYS.LOGS, JSON.stringify([]));

  // 2. Try to fetch fresh data from Google Sheet (Async)
  // We fetch all in parallel for speed
  const [users, production, offDays, logs] = await Promise.all([
    fetchFromSheet('Users'),
    fetchFromSheet('Production'),
    fetchFromSheet('OffDays'),
    fetchFromSheet('Logs')
  ]);

  let hasChanges = false;

  if (users) { localStorage.setItem(KEYS.USERS, JSON.stringify(users)); hasChanges = true; }
  if (production) { localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(production)); hasChanges = true; }
  if (offDays) { localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(offDays)); hasChanges = true; }
  if (logs) { localStorage.setItem(KEYS.LOGS, JSON.stringify(logs)); hasChanges = true; }

  // 3. Notify App to Re-render if we got new data
  if (hasChanges) {
    notifyChange();
  }
};

// Start sync on load
init();

export const StorageService = {
  // Subscribe to changes (used by Context)
  subscribe: (callback: () => void) => {
    listeners.push(callback);
    return () => {
      const index = listeners.indexOf(callback);
      if (index > -1) listeners.splice(index, 1);
    };
  },

  // Users
  getUsers: (): User[] => JSON.parse(localStorage.getItem(KEYS.USERS) || '[]'),
  saveUsers: (users: User[]) => {
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
    syncToSheet('Users', users);
    notifyChange();
  },

  // Production
  getProductionData: (): ProductionEntry[] => JSON.parse(localStorage.getItem(KEYS.PRODUCTION) || '[]'),
  saveProductionData: (data: ProductionEntry[]) => {
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(data));
    syncToSheet('Production', data);
    notifyChange();
  },

  // Off Days
  getOffDays: (): OffDay[] => JSON.parse(localStorage.getItem(KEYS.OFF_DAYS) || '[]'),
  saveOffDays: (days: OffDay[]) => {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(days));
    syncToSheet('OffDays', days);
    notifyChange();
  },

  // Logs
  getLogs: (): ActivityLog[] => JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]'),
  addLog: (log: Omit<ActivityLog, 'id' | 'timestamp'>) => {
    const logs = StorageService.getLogs();
    const newLog: ActivityLog = {
      ...log,
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
    };
    logs.unshift(newLog); 
    if (logs.length > 1000) logs.pop();

    localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));
    syncToSheet('Logs', logs);
    notifyChange();
  },

  // Session (No sync needed for session)
  getSession: (): User | null => {
    const session = localStorage.getItem(KEYS.CURRENT_USER);
    return session ? JSON.parse(session) : null;
  },
  setSession: (user: User | null) => {
    if (user) localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
    else localStorage.removeItem(KEYS.CURRENT_USER);
    notifyChange();
  }
};
```

## src/contexts/DashboardContext.tsx

I have added a `useEffect` hook here that subscribes to the `StorageService`. This means as soon as the data arrives from Google Sheets, `triggerRefresh()` is called automatically, updating your dashboard instantly.

```tsx
import React, { createContext, useContext, useState, useEffect } from 'react';
import type { ReactNode } from 'react';
import type { Category } from '../types';
import { StorageService } from '../services/storageService';

interface DashboardContextType {
  category: Category;
  setCategory: (c: Category) => void;
  isDarkMode: boolean;
  toggleDarkMode: () => void;
  refreshKey: number;
  triggerRefresh: () => void;
}

const DashboardContext = createContext<DashboardContextType | undefined>(undefined);

export const DashboardProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [category, setCategory] = useState<Category>('Healthcare');
  const [refreshKey, setRefreshKey] = useState(0);
  const [isDarkMode, setIsDarkMode] = useState(false);

  useEffect(() => {
    if (localStorage.getItem('theme') === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }

    // Subscribe to Storage updates (Google Sheet loads, Inputs, etc)
    const unsubscribe = StorageService.subscribe(() => {
      setRefreshKey(prev => prev + 1);
    });

    return () => unsubscribe();
  }, []);

  const toggleDarkMode = () => {
    setIsDarkMode(prev => {
      const newVal = !prev;
      if (newVal) {
        document.documentElement.classList.add('dark');
        localStorage.setItem('theme', 'dark');
      } else {
        document.documentElement.classList.remove('dark');
        localStorage.setItem('theme', 'light');
      }
      return newVal;
    });
  };

  const triggerRefresh = () => setRefreshKey(prev => prev + 1);

  return (
    <DashboardContext.Provider value={{ category, setCategory, isDarkMode, toggleDarkMode, refreshKey, triggerRefresh }}>
      {children}
    </DashboardContext.Provider>
  );
};

export const useDashboard = () => {
  const context = useContext(DashboardContext);
  if (!context) throw new Error('useDashboard must be used within DashboardProvider');
  return context;
};

To fix the date formatting issues and ensure everything runs in the **Malaysia Timezone (MYT)**, we need to standardize how dates are created, saved, and displayed across the app.

Here is the plan:
1.  **Create a Date Utility Helper**: A single place to handle timezone conversions so we don't repeat code.
2.  **Update Input Modals**: To use the correct local date when saving.
