```typescript
export const getMalaysiaDate = () => {
  // Returns current date in Malaysia as Date object
  const now = new Date();
  const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
  const malaysiaTime = new Date(utc + (3600000 * 8)); // UTC + 8
  return malaysiaTime;
};

export const getTodayISO = () => {
  // Returns YYYY-MM-DD for input fields based on Malaysia time
  const myt = getMalaysiaDate();
  return myt.toISOString().split('T')[0];
};

export const formatDisplayDate = (dateStr: string) => {
  // Input: YYYY-MM-DD (e.g., "2025-12-25")
  // Output: "2025-12-25 THURSDAY"
  if (!dateStr) return 'Invalid Date';

  const date = new Date(dateStr);
  // We need to prevent timezone shift when parsing YYYY-MM-DD
  // A simple trick is appending the time to force local parsing or just using getUTCDay if the string is strict
  // Let's use a safe formatter

  const options: Intl.DateTimeFormatOptions = { 
    weekday: 'long', 
    year: 'numeric', 
    month: '2-digit', 
    day: '2-digit',
    timeZone: 'Asia/Kuala_Lumpur'
  };

  // Create date object treating the string as midnight local time
  // Safest way to parse YYYY-MM-DD without timezone shift:
  const [y, m, d] = dateStr.split('-').map(Number);
  const localDate = new Date(y, m - 1, d);

  const dayName = localDate.toLocaleDateString('en-MY', { weekday: 'long' });

  // Return format: 2025-12-25 Thursday
  return `${dateStr} ${dayName}`;
};
