export const getMalaysiaDate = () => {
  // Returns current date in Malaysia as Date object
  const now = new Date();
  const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
  const malaysiaTime = new Date(utc + (3600000 * 8)); // UTC + 8
  return malaysiaTime;
};

export const getTodayISO = () => {
  // Returns YYYY-MM-DD for input fields based on Malaysia time
  const myt = getMalaysiaDate();
  // We construct the string manually to ensure it doesn't revert to UTC
  const year = myt.getFullYear();
  const month = String(myt.getMonth() + 1).padStart(2, '0');
  const day = String(myt.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export const formatDisplayDate = (dateStr: string) => {
  // Input: "2025-12-25" OR "2025-12-24T16:00:00.000Z"
  // Output: "25-12-2025 Thursday" (Always in MYT)

  if (!dateStr) return 'Invalid Date';

  let year, month, day;

  // Handle Full ISO Strings (which might look like the day before in UTC)
  if (dateStr.includes('T')) {
    const d = new Date(dateStr);
    // Convert logic: Add 8 hours to UTC time
    // Note: getUTCHours/etc works on the underlying time value
    // We want to force the visual date to be +8 hours from the ISO string's UTC point
    const offset = 8 * 60 * 60 * 1000; // 8 hours in ms
    const mytDate = new Date(d.getTime() + offset);

    // Use getUTC methods on the shifted time to get the "Malaysia Face Value"
    year = mytDate.getUTCFullYear();
    month = mytDate.getUTCMonth() + 1;
    day = mytDate.getUTCDate();
  } 
  // Handle Simple YYYY-MM-DD Strings
  else {
    const parts = dateStr.split('-');
    year = Number(parts[0]);
    month = Number(parts[1]);
    day = Number(parts[2]);
  }

  // Validation
  if (isNaN(year) || isNaN(month) || isNaN(day)) return 'Invalid Date';

  // Construct Date object for Day Name (Month is 0-indexed in JS Date)
  const localDate = new Date(year, month - 1, day);
  const dayName = localDate.toLocaleDateString('en-MY', { weekday: 'long' });

  // Format with padding: DD-MM-YYYY
  const dd = String(day).padStart(2, '0');
  const mm = String(month).padStart(2, '0');

  return `${dd}-${mm}-${year} ${dayName}`;
};

