export const getMalaysiaDate = () => {
  // Returns current date in Malaysia as Date object
  const now = new Date();
  const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
  const malaysiaTime = new Date(utc + (3600000 * 8)); // UTC + 8
  return malaysiaTime;
};

export const getTodayISO = () => {
  // Returns YYYY-MM-DD for input fields based on Malaysia time
  const myt = getMalaysiaDate();
  const year = myt.getFullYear();
  const month = String(myt.getMonth() + 1).padStart(2, '0');
  const day = String(myt.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export const normalizeDate = (dateStr: string) => {
  // Helper to ensure we always compare YYYY-MM-DD
  if (!dateStr) return '';

  // If it's a full ISO string (e.g. from DB), convert to MYT YYYY-MM-DD
  if (dateStr.includes('T')) {
     const d = new Date(dateStr);
     const offset = 8 * 60 * 60 * 1000;
     const mytDate = new Date(d.getTime() + offset);
     return mytDate.toISOString().split('T')[0];
  }

  // If it's already YYYY-MM-DD, just return it
  return dateStr;
};

export const formatDisplayDate = (dateStr: string) => {
  // Input: "2025-12-25" or ISO
  // Output: "2025-12-25 THURSDAY" (Matches your screenshot)

  if (!dateStr) return 'Invalid Date';

  // Normalize to YYYY-MM-DD
  const cleanDateStr = normalizeDate(dateStr);
  const [yearStr, monthStr, dayStr] = cleanDateStr.split('-');
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);

  // Validation
  if (isNaN(year) || isNaN(month) || isNaN(day)) return 'Invalid Date';

  // Construct Date object for Day Name
  const localDate = new Date(year, month - 1, day);
  const dayName = localDate.toLocaleDateString('en-MY', { weekday: 'long' }).toUpperCase();

  // Return format: YYYY-MM-DD DAYNAME
  return `${year}-${monthStr}-${dayStr} ${dayName}`;
};
