    const sortedDates = Array.from(uniqueDates).sort((a, b) => b.localeCompare(a));

    // 3. Create groups
    const groups = sortedDates.map(date => {
        const entries = filteredData.filter(p => normalizeDate(p.date) === date);
        const offDay = offDays.find(od => normalizeDate(od.date) === date);

        return {
            date,
            entries,
            offDay: offDay?.description
        };
    });

    return groups;
  }, [filteredData, offDays, viewMode, dateRange]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Delete this record?")) return;
      const newData = productionData.filter(p => p.id !== id);
      StorageService.saveProductionData(newData);
      triggerRefresh();
      notify('info', 'Record deleted successfully.');
  };

  const calculateEfficiency = (actual: number, plan: number) => {
    if (plan === 0) return 0;
    return ((actual / plan) * 100).toFixed(0);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';

    if (viewMode === 'daily') {
        headers = ["Date", "Day", "Category", "Process", "Product", "Plan", "Actual", "Efficiency %", "Batch No", "Manpower"];
        // For export, we use filteredData directly
        rows = filteredData.map(d => {
