    const relevant = productionData.filter(d => d.category === category);

    let totalPlan = 0;
    let totalActual = 0;

    const processMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    const monthlyGroups: Record<string, { plan: number, actual: number }> = {};

    relevant.forEach(d => {
      totalPlan += d.planQuantity;
      totalActual += d.actualQuantity;

      if (!processMap.has(d.process)) {
        processMap.set(d.process, { process: d.process, Plan: 0, Actual: 0 });
      }
      const p = processMap.get(d.process)!;
      p.Plan += d.planQuantity;
      p.Actual += d.actualQuantity;

      // Safe monthly grouping
      const cleanDate = normalizeDate(d.date);
      const monthKey = cleanDate.substring(0, 7); // YYYY-MM

      if (!monthlyGroups[monthKey]) {
          monthlyGroups[monthKey] = { plan: 0, actual: 0 };
      }
      monthlyGroups[monthKey].plan += d.planQuantity;
      monthlyGroups[monthKey].actual += d.actualQuantity;
    });

    const monthlyStats = Object.entries(monthlyGroups)
        .map(([month, s]) => ({
            month,
            plan: s.plan,
            actual: s.actual,
            efficiency: s.plan > 0 ? (s.actual / s.plan) * 100 : 0
        }))
        .sort((a, b) => b.month.localeCompare(a.month));

    return {
      filteredData: relevant,
      stats: { totalPlan, totalActual },
      chartData: Array.from(processMap.values()),
      monthlyData: monthlyStats
    };
  }, [productionData, category]);

  // Group data by Date for Daily View (DATA DRIVEN ONLY)
  const dailyGroups = useMemo(() => {
    if (viewMode === 'monthly') return [];

    // 1. Collect all unique dates from the filtered data AND off days
    const uniqueDates = new Set<string>();

    // Add production dates
    filteredData.forEach(d => {
        const normalized = normalizeDate(d.date);
        // Apply date range filter only if set
        if ((!dateRange.start || normalized >= dateRange.start) && 
            (!dateRange.end || normalized <= dateRange.end)) {
            uniqueDates.add(normalized);
        }
    });

    // Add off day dates
    offDays.forEach(od => {
        const normalized = normalizeDate(od.date);
        if ((!dateRange.start || normalized >= dateRange.start) && 
            (!dateRange.end || normalized <= dateRange.end)) {
            uniqueDates.add(normalized);
        }
    });

    // 2. Sort dates descending (newest first)
    const sortedDates = Array.from(uniqueDates).sort((a, b) => b.localeCompare(a));

    // 3. Create groups
    const groups = sortedDates.map(date => {
        const entries = filteredData.filter(p => normalizeDate(p.date) === date);
        const offDay = offDays.find(od => normalizeDate(od.date) === date);

        return {
            date,
            entries,
            offDay: offDay?.description
        };
