                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="process" tick={{fontSize: 12, fill: '#64748b'}} axisLine={false} tickLine={false} />
                <YAxis tick={{fontSize: 12, fill: '#64748b'}} axisLine={false} tickLine={false} />
                <Tooltip 
                    contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1)' }}
                    cursor={{fill: 'transparent'}}
                />
                <Legend />
                <Bar dataKey="Plan" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40} />
                <Bar dataKey="Actual" fill="#10b981" radius={[4, 4, 0, 0]} barSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
      </div>

      {/* Production Log */}
      <div className="glass-panel rounded-2xl overflow-hidden min-h-[400px] flex flex-col">
        <div className="p-5 border-b border-gray-100 dark:border-slate-700/50 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white/50 dark:bg-slate-800/50">
            <div className="flex flex-col gap-1">
                <h3 className="font-bold text-lg flex items-center gap-2 text-slate-700 dark:text-slate-200">
                    <i className="fas fa-table text-indigo-500"></i> Production Log
