                        <span className="text-gray-400">to</span>
                        <input type="date" value={dateRange.end} onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))} className="border rounded p-1 dark:bg-slate-800 dark:border-slate-700"/>
                    </div>
                )}
