            </div>
        </div>

        <div className="p-4 space-y-6 flex-1 bg-gray-50/50 dark:bg-slate-900/20">
            {/* DAILY VIEW - GROUPED BY DATE */}
            {viewMode === 'daily' && (
                <>
                    {dailyGroups.length === 0 && (
                        <div className="flex flex-col items-center justify-center h-48 text-slate-400">
                            <p>No data recorded in selected range.</p>
                        </div>
                    )}

                    {dailyGroups.map((group, idx) => {
                        // 1. Get display string for the current group (e.g. "2025-12-25 THURSDAY")
                        const fullDateStr = formatDisplayDate(group.date);
                        const [datePart, ...dayParts] = fullDateStr.split(' ');
                        const dayNamePart = dayParts.join(' ');

                        // 2. STRICT MONTH HEADER LOGIC: 
                        // Parse the group.date (YYYY-MM-DD) directly to get YYYY and MM
                        const [currYear, currMonth] = group.date.split('-'); 

                        const dateObj = new Date(Number(currYear), Number(currMonth) - 1, 1);
                        const monthStr = dateObj.toLocaleString('en-US', { month: 'short', year: 'numeric' }).toUpperCase();

                        let showMonthHeader = idx === 0;
                        if (idx > 0) {
                            const prevGroup = dailyGroups[idx - 1];
                            const [prevYear, prevMonth] = prevGroup.date.split('-');
                            // Show header if Month OR Year changed
                            showMonthHeader = (prevYear !== currYear) || (prevMonth !== currMonth);
                        }

                        const totalDailyActual = group.entries.reduce((sum, e) => sum + e.actualQuantity, 0);

                        return (
                            <React.Fragment key={group.date}>
                                {showMonthHeader && (
                                    <div className="relative text-center my-8">
                                        <span className="bg-gray-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 px-4 py-1 rounded-full text-xs font-bold uppercase tracking-wider relative z-10">
                                            {monthStr}
                                        </span>
                                        <div className="absolute top-1/2 left-0 w-full h-px bg-gray-300 dark:bg-slate-700 -z-0"></div>
                                    </div>
                                )}

                                <div className={`rounded-xl overflow-hidden shadow-sm border border-gray-200 dark:border-slate-700 mb-4 ${group.offDay ? 'bg-red-50 dark:bg-red-900/10' : 'bg-white dark:bg-slate-800'}`}>
                                    {/* Date Header */}
                                    <div className={`p-4 flex flex-wrap justify-between items-center ${group.offDay ? 'bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-200' : 'bg-slate-800 text-white'}`}>
                                        <div className="flex items-center gap-3">
                                            <span className="text-lg font-bold"><i className="fas fa-calendar-day mr-2 opacity-70"></i>{datePart}</span>
                                            <span className="text-xs font-medium opacity-70 uppercase tracking-wide bg-black/20 px-2 py-0.5 rounded">{dayNamePart}</span>
                                            {group.offDay && <span className="bg-red-600 text-white px-3 py-0.5 rounded text-xs font-bold uppercase tracking-wider">OFF DAY: {group.offDay}</span>}
                                        </div>
                                        {!group.offDay && group.entries.length > 0 && (
                                            <div className="bg-slate-700 dark:bg-slate-900 px-3 py-1 rounded-lg text-xs font-bold text-white border border-slate-600">
                                                Total Actual: {totalDailyActual}
                                            </div>
                                        )}
                                    </div>

                                    {/* Production Table or Off Day Message */}
                                    {group.entries.length > 0 ? (
                                        <div className="overflow-x-auto">
                                            <table className="w-full text-sm text-left">
                                                <thead className="bg-gray-50 dark:bg-slate-900/50 text-gray-500 dark:text-gray-400 font-bold text-[10px] uppercase border-b border-gray-100 dark:border-slate-700">
                                                    <tr>
                                                        <th className="px-4 py-3">Process</th>
                                                        <th className="px-4 py-3">Product</th>
                                                        <th className="px-4 py-3 text-right text-blue-600 dark:text-blue-400">Plan Qty</th>
                                                        <th className="px-4 py-3 text-right text-emerald-600 dark:text-emerald-400">Actual Qty</th>
                                                        <th className="px-4 py-3 text-center">Efficiency</th>
                                                        <th className="px-4 py-3 text-center">Batch No</th>
                                                        <th className="px-4 py-3 text-center">Manpower</th>
                                                        {hasPermission(['manager', 'admin']) && <th className="px-4 py-3 text-center">Action</th>}
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                                                    {group.entries.map(entry => {
                                                        const eff = Number(calculateEfficiency(entry.actualQuantity, entry.planQuantity));
                                                        let effColor = 'text-red-500 font-bold';
                                                        if(eff >= 80) effColor = 'text-emerald-500 font-bold';
                                                        else if(eff >= 50) effColor = 'text-yellow-500 font-bold';

                                                        return (
                                                            <tr key={entry.id} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition">
                                                                <td className="px-4 py-3">
                                                                    <span className="bg-indigo-50 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-300 px-2 py-1 rounded text-xs font-bold border border-indigo-100 dark:border-indigo-800">
                                                                        {entry.process}
                                                                    </span>
                                                                </td>
                                                                <td className="px-4 py-3 font-bold text-slate-700 dark:text-slate-200">{entry.productName}</td>
                                                                <td className="px-4 py-3 text-right font-mono text-blue-600 dark:text-blue-400 font-bold">{entry.planQuantity}</td>
                                                                <td className="px-4 py-3 text-right font-mono text-emerald-600 dark:text-emerald-400 font-bold">{entry.actualQuantity}</td>
                                                                <td className={`px-4 py-3 text-center ${effColor}`}>
                                                                    {eff}%
                                                                </td>
                                                                <td className="px-4 py-3 text-center font-mono text-xs text-slate-500 dark:text-gray-400">{entry.batchNo || '-'}</td>
                                                                <td className="px-4 py-3 text-center font-bold dark:text-gray-300">{entry.manpower || 0}</td>
                                                                {hasPermission(['manager', 'admin']) && (
                                                                    <td className="px-4 py-3 text-center flex justify-center gap-2">
                                                                        <button 
                                                                            onClick={() => setEditingEntry(entry)}
                                                                            className="text-indigo-400 hover:text-indigo-600 transition-colors p-1.5 rounded-full hover:bg-indigo-50 dark:hover:bg-indigo-900/20"
                                                                            title="Edit Entry"
                                                                        >
                                                                            <Edit2 className="w-4 h-4" />
                                                                        </button>
                                                                        <button 
                                                                            onClick={() => handleDelete(entry.id)}
                                                                            className="text-gray-400 hover:text-red-500 transition-colors p-1.5 rounded-full hover:bg-red-50 dark:hover:bg-red-900/20"
                                                                            title="Delete Entry"
                                                                        >
                                                                            <Trash2 className="w-4 h-4" />
                                                                        </button>
                                                                    </td>
                                                                )}
                                                            </tr>
                                                        );
                                                    })}
                                                </tbody>
                                            </table>
                                        </div>
                                    ) : (
                                        <div className={`p-8 text-center flex flex-col items-center justify-center ${group.offDay ? 'text-red-500' : 'text-gray-400'}`}>
                                            {group.offDay ? (
                                                <>
                                                    <CalendarOff className="w-8 h-8 mb-2 opacity-50" />
                                                    <span className="font-bold text-lg uppercase tracking-widest">{group.offDay}</span>
                                                    <span className="text-xs opacity-70 mt-1">Production Halted</span>
                                                </>
                                            ) : null}
                                        </div>
                                    )}
                                </div>
                            </React.Fragment>
                        );
                    })}
                </>
            )}

            {/* MONTHLY SUMMARY VIEW */}
            {viewMode === 'monthly' && (
                <div className="overflow-x-auto bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-200 dark:border-slate-700">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-gray-100 dark:bg-slate-700 text-gray-700 dark:text-slate-200">
                            <tr>
                                <th className="px-6 py-4 rounded-l-lg">Month</th>
                                <th className="px-6 py-4 text-right">Total Plan</th>
                                <th className="px-6 py-4 text-right">Total Actual</th>
                                <th className="px-6 py-4 text-right">Overall Eff.</th>
                                <th className="px-6 py-4 rounded-r-lg text-center">Status</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                            {monthlyData.length === 0 ? (
                                <tr><td colSpan={5} className="text-center py-8 text-gray-400">No data available</td></tr>
                            ) : monthlyData.map(m => (
                                <tr key={m.month} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition">
                                    <td className="px-6 py-4 font-bold text-gray-800 dark:text-white">
                                        {new Date(m.month + '-01').toLocaleDateString('default', { month: 'long', year: 'numeric' })}
                                    </td>
                                    <td className="px-6 py-4 text-right font-mono text-blue-600 dark:text-blue-400 font-bold">{m.plan.toLocaleString()}</td>
                                    <td className="px-6 py-4 text-right font-mono text-emerald-600 dark:text-emerald-400 font-bold">{m.actual.toLocaleString()}</td>
                                    <td className="px-6 py-4 text-right">
                                        <span className={`font-bold ${m.efficiency >= 80 ? 'text-emerald-600' : 'text-red-500'}`}>{m.efficiency.toFixed(1)}%</span>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wide ${
                                            m.efficiency >= 90 ? 'bg-emerald-100 text-emerald-700' : 
                                            m.efficiency >= 80 ? 'bg-blue-100 text-blue-700' : 'bg-red-100 text-red-700'
                                        }`}>
                                            {m.efficiency >= 90 ? 'Excellent' : m.efficiency >= 80 ? 'Good' : 'Review'}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
      </div>

      {editingEntry && (
        <EditEntryModal 
            entry={editingEntry} 
            onClose={() => setEditingEntry(null)} 
        />
      )}
    </div>
  );
};

