                  <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                    {dashboardData.monthlySummary.length === 0 ? (
                      <tr><td colSpan={6} className="text-center py-12 text-gray-400 font-bold">No historical data found</td></tr>
                    ) : dashboardData.monthlySummary.map((m, idx) => (
                      <tr key={`${m.month}-${m.process}-${idx}`} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition-colors">
                        <td className="px-6 py-4 font-black text-slate-700 dark:text-white bg-slate-50 dark:bg-slate-900/50">
                          {getMonthName(m.month)}
