                        <td className="px-6 py-4">
                          <span className="px-3 py-1 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-300 rounded-lg text-xs font-black uppercase tracking-tight">
                            {m.process}
