                        </td>
                        <td className="px-6 py-4 text-right font-black text-blue-600 dark:text-blue-400">
                          {m.plan.toLocaleString()}
                        </td>
                        <td className="px-6 py-4 text-right font-black text-emerald-600 dark:text-emerald-400">
                          {m.actual.toLocaleString()}
                        </td>
                        <td className="px-6 py-4 text-center">
                          <div className="flex flex-col items-center gap-1">
                            <span className={`font-black ${m.efficiency >= 80 ? 'text-emerald-600' : 'text-red-500'}`}>
                              {m.efficiency.toFixed(1)}%
                            </span>
                            <div className="w-16 h-1 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden">
                              <div className={`h-full ${m.efficiency >= 80 ? 'bg-emerald-500' : 'bg-red-500'}`} style={{ width: `${Math.min(m.efficiency, 100)}%` }}></div>
                            </div>
