// Seed some data for visualization
export const generateSeedProductionData = (): ProductionEntry[] => {
  const data: ProductionEntry[] = [];
  const products = ['Pain Relief Gel', 'Minty Fresh', 'Pink Salt Fine', 'Vitamin C', 'Charcoal Paste'];
  const today = new Date();

  for (let i = 0; i < 30; i++) {
    const d = new Date(today);
    d.setDate(today.getDate() - i);
    const dateStr = d.toISOString().split('T')[0];

    products.forEach((prod, idx) => {
      // Randomly skip some days
      if (Math.random() > 0.8) return;

      const plan = Math.floor(Math.random() * 500) + 500;
      // Actual is sometimes matching, sometimes less, rarely more
      const variance = (Math.random() * 0.4) - 0.1; // -10% to +30% shortfall
      const actual = Math.floor(plan * (1 - variance));

      data.push({
        id: `seed-${i}-${idx}`,
        date: dateStr,
        category: idx % 3 === 0 ? 'Healthcare' : idx % 3 === 1 ? 'Toothpaste' : 'Rocksalt',
        process: PROCESSES[idx % 5],
        productName: prod,
        planQuantity: plan,
        actualQuantity: actual,
        batchNo: `B-${dateStr.replace(/-/g, '')}-${idx}`,
        manpower: Math.floor(Math.random() * 5) + 3,
        lastUpdatedBy: 'u1',
        updatedAt: new Date().toISOString()
      });
    });
  }
  return data;
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User, Role } from '../types';
import { StorageService } from '../services/storageService';
import { INITIAL_USERS } from '../constants';

interface AuthContextType {
  user: User | null;
  login: (username: string, pass: string) => boolean;
  logout: () => void;
  hasPermission: (roles: Role[]) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    const session = StorageService.getSession();
    if (session) {
      setUser(session);
    }
  }, []);

  const login = (username: string, pass: string) => {
    const storedUsers = StorageService.getUsers();
    // Combine initial and stored users, prioritizing stored ones if there's conflict
    const userMap = new Map<string, User>();
    [...INITIAL_USERS, ...storedUsers].forEach(u => userMap.set(u.username.toLowerCase(), u));

    const targetUser = userMap.get(username.toLowerCase());

    if (targetUser && targetUser.password === pass) {
      setUser(targetUser);
      StorageService.setSession(targetUser);
      return true;
    }
    return false;
  };

  const logout = () => {
    setUser(null);
    StorageService.setSession(null);
  };

  const hasPermission = (allowedRoles: Role[]) => {
    if (!user) return false;
    return allowedRoles.includes(user.role);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, hasPermission }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

