      {notifications.map((n) => (
        <div 
          key={n.id}
          className={`
            pointer-events-auto flex items-center gap-3 px-4 py-3 rounded-2xl shadow-2xl border animate-in slide-in-from-top-4 duration-300
            ${n.type === 'success' ? 'bg-emerald-600 border-emerald-500 text-white' : ''}
            ${n.type === 'error' ? 'bg-red-600 border-red-500 text-white' : ''}
            ${n.type === 'info' ? 'bg-indigo-600 border-indigo-500 text-white' : ''}
          `}
        >
          {n.type === 'success' && <CheckCircle className="w-5 h-5 flex-shrink-0" />}
          {n.type === 'error' && <AlertCircle className="w-5 h-5 flex-shrink-0" />}
          {n.type === 'info' && <Info className="w-5 h-5 flex-shrink-0" />}

          <p className="text-sm font-bold flex-1">{n.message}</p>

          <button 
            onClick={() => hideNotification(n.id)}
            className="p-1 hover:bg-white/20 rounded-lg transition"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      ))}
    </div>
  );
};

import React from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider } from './contexts/AuthContext';
import { DashboardProvider } from './contexts/DashboardContext';
import { NotificationProvider } from './contexts/NotificationContext';
import { Layout } from './components/ui/Layout';
import { Dashboard } from './components/pages/Dashboard';

const App: React.FC = () => {
  return (
    <HashRouter>
      <NotificationProvider>
        <AuthProvider>
          <DashboardProvider>
            <Routes>
              <Route path="/" element={<Layout><Dashboard /></Layout>} />
              <Route path="*" element={<Navigate to="/" replace />} />
            </Routes>
          </DashboardProvider>
        </AuthProvider>
      </NotificationProvider>
    </HashRouter>
  );
};

export default App;
